import { Prism, languages, insertBefore } from '../prismCore'
import './markup'
import './csharp'

var pageDirectiveInside = {
	'page-directive': {
		pattern: /<%\s*@\s*(?:Assembly|Control|Implements|Import|Master(?:Type)?|OutputCache|Page|PreviousPageType|Reference|Register)?|%>/i,
		alias: 'tag'
	}
}

var aspnet = languages.aspnet = languages.extend('markup', {
	'page-directive': {
		pattern: /<%\s*@.*%>/,
		alias: 'tag',
		inside: pageDirectiveInside
	},
	'directive': {
		pattern: /<%.*%>/,
		alias: 'tag',
		inside: {
			'directive': {
				pattern: /<%\s*?[$=%#:]{0,2}|%>/,
				alias: 'tag'
			},
			rest: 'csharp'
		}
	}
});

var brackets = aspnet['markup-bracket'];
var tag = aspnet.tag;
delete aspnet['markup-bracket'];

aspnet['markup-bracket'] = brackets;
pageDirectiveInside.rest = tag.inside;

// Regexp copied from prism-markup, with a negative look-ahead added
tag.pattern = /<(?!%)\/?[^\s>\/]+(?:\s+[^\s>\/=]+(?:=(?:("|')(?:\\[\s\S]|(?!\1)[^\\])*\1|[^\s'">=]+))?)*\s*\/?>/;

// match directives of attribute value foo="<% Bar %>"
insertBefore('inside', 'punctuation', {
	'directive': aspnet['directive']
}, tag.inside['attr-value']);

insertBefore('aspnet', 'comment', {
	'asp-comment': {
		pattern: /<%--[\s\S]*?--%>/,
		alias: ['asp', 'comment']
	}
});

// script runat="server" contains csharp, not javascript
insertBefore('aspnet', aspnet.script ? 'script' : 'tag', {
	'asp-script': {
		pattern: /(<script(?=.*runat=['"]?server\b)[^>]*>)[\s\S]*?(?=<\/script>)/i,
		lookbehind: true,
		alias: ['asp', 'script'],
		inside: 'csharp'
	}
});
